Algorithm Subidas
  Dimension t[4] As Integer;
  t[0] <- 20;
  t[1] <- 22;
  t[2] <- 21;
  t[3] <- 25;
  Define subidas As Integer <- 0;
  For i <- 1 To 3 Do
    If t[i] > t[i - 1] Then
      subidas <- subidas + 1;
    EndIf
  EndFor
  Write subidas;
EndAlgorithm

Algorithm Olas
  Dimension t[14] As Integer;
  For i <- 0 To 13 Do
    Read t[i];
  EndFor
  Define racha As Integer <- 0;
  Define olas As Integer <- 0;
  Define masLarga As Integer <- 0;
  For Each temperatura In t Do
    If temperatura > 30 Then
      racha <- racha + 1;
    Else
      If racha >= 3 Then
        olas <- olas + 1;
        If racha > masLarga Then
          masLarga <- racha;
        EndIf
      EndIf
      racha <- 0;
    EndIf
  EndFor
  If racha >= 3 Then
    olas <- olas + 1;
    If racha > masLarga Then
      masLarga <- racha;
    EndIf
  EndIf
  Write "Olas: ", olas;
  Write "La más larga: ", masLarga;
EndAlgorithm
